<script lang="ts">import {goto} from '$app/navigation';import {auth} from '$lib/api';import {session} from '$lib/stores/session';import TopNav from '$lib/components/TopNav.svelte';let email=$state(''),password=$state(''),error=$state(''),loading=$state(false);async function submit(){if(!email||!password){error='Enter your email and password.';return}loading=true;error='';try{const {user}=await auth.login(email,password);session.set(user);await goto('/dashboard')}catch(e){error=e instanceof Error?e.message:'Unable to log in.'}finally{loading=false}}</script>
<svelte:head><title>Login · RegenFeed</title></svelte:head><TopNav/><main class="stitch-auth stitch-login"><form class="stitch-card" onsubmit={(e)=>{e.preventDefault();submit()}}><div class="stitch-heading"><h1>Welcome Back</h1><p>Please enter your details to sign in.</p></div>{#if error}<p class="error" role="alert">{error}</p>{/if}<label>Email<div class="stitch-input"><input bind:value={email} type="email" autocomplete="email" placeholder="Enter your email" required /></div></label><div class="stitch-password-row"><label>Password<div class="stitch-input"><input bind:value={password} type="password" autocomplete="current-password" placeholder="••••••••" required /></div></label><a href="/auth/forgot-password">Forgot Password?</a></div><button class="stitch-button" disabled={loading}>{loading?'Signing in…':'Sign In'} <i class="fa-solid fa-arrow-right"></i></button><p class="stitch-switch">Don't have an account? <a href="/auth/register">Sign Up</a></p></form></main>
